// th15_s1_b1 — TH15 v1.00b Stage 1 Boss non-spell 1.
// Source: st01bs.ecl.txt::Boss1 (lines 49-78) with dependencies Boss1_at (80-171),
// Boss1_at2 (173-229); entry state reconstructed from st01bs.ecl.txt::Boss (8-47).
// Source local frame 0 = card frame OPENING_BUFFER (120). Window = setInterrupt timeout 2280.
//
// Boss1_at's `A/B/C` parameters have no live consumer in the source: B is never read,
// and C only feeds the `%A = %A + %C` accumulator at 0155 which no instruction ever reads.
// The actual fan spreads are literals inside each block (block1 0.034906585rad = 2deg;
// block2 pushes 25/20/15/12deg). So both call sites therefore emit identical behaviour.

const TIME_LIMIT: int = 2404;        // 120 opening buffer + 2280 window + 4 startup margin
const OPENING_BUFFER: int = 120;

// moveLimit(0,128,280,64): full width/height -> x in [-140,140], y in [96,160].
// Direction-choice interior is center +/- width/height/4 -> x +/-70, y 112..144.
const MV_BOUND_X: fx = 140fx;
const MV_BOUND_Y0: fx = 96fx;
const MV_BOUND_Y1: fx = 160fx;
const MV_INNER_X: fx = 70fx;
const MV_INNER_Y0: fx = 112fx;
const MV_INNER_Y1: fx = 144fx;

// ---------------- source moveRand(60, 4, 1.0) ----------------
// Reuses the approved modern moveRand recipe: speed(k) = 1 - k/60, per-frame position
// clamp (no reflection). Shared int slot0 = step count; fx slots0/1 = logical unit vector.
sub mv_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -MV_BOUND_X { nx = -MV_BOUND_X; }
    if nx > MV_BOUND_X { nx = MV_BOUND_X; }
    if ny < MV_BOUND_Y0 { ny = MV_BOUND_Y0; }
    if ny > MV_BOUND_Y1 { ny = MV_BOUND_Y1; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub mv_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    mv_step();
}

sub mv_rand() {
    // signed unit random * pi, in unwrapped BAM ints
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -MV_INNER_X {
        a = r / 3;
    } else if $self_x > MV_INNER_X {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < MV_INNER_Y0 {
        if a < 0 { a = -a; }
    } else if $self_y > MV_INNER_Y1 {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +/-pi/2 guard, epsilon 0.05rad (nearest BAM boundaries)
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    mv_begin(a as angle);
}

sub mv_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        mv_step();
    }
}

// ---------------- emitters ----------------
// Source fixed-direction fan (etAim mode1): N paths, spacing `spread`, centered on `aim0`,
// single speed. Each bullet carries ANIM (a=1) which keeps the birth retro-displacement
// position -= 4*velocity; birth slow-down / hit-less window are omitted per policy.
sub fire_fan(shape: int, color: int, aim0: angle, n: int, spread: angle, spd: fx) {
    var d: int = spread as int;
    var back: fx = 4fx * spd;
    for i in 0..n {
        var off: int = ((i + 1) / 2) * d;
        if n % 2 == 0 { off = (i / 2) * d + d / 2; }
        if i % 2 != 0 { off = -off; }
        var a: angle = aim0 + (off as angle);
        var bx: fx = $self_x - back * cos(a);
        var by: fx = $self_y - back * sin(a);
        _ = fire(shape, color, bx, by, spd, a, none, none);
    }
}

// Source fixed-direction ring (etAim mode3) with 1 path: M speed layers share one base
// angle; layer speed v(q) = s0 + (s1-s0)*q/(M-1).
sub fire_stack(shape: int, color: int, base: angle, m: int, s0: fx, s1: fx) {
    for q in 0..m {
        var v: fx = s0;
        if m > 1 { v = s0 + (s1 - s0) * q / (m - 1); }
        var back: fx = 4fx * v;
        var bx: fx = $self_x - back * cos(base);
        var by: fx = $self_y - back * sin(base);
        _ = fire(shape, color, bx, by, v, base, none, none);
    }
}

// ---------------- Boss1_at (source 80-171) ----------------
async sub boss1_at() {
    var rank: int = global(GVAR_RANK);
    var g: int = 12;      // loop count (source diffI $G = 4/8/8/12)
    var w: int = 4;       // inter-wave wait (source 6/6/6/4)
    var s1: fx = 4.1fx;   // block1 speed  (1.5/2.5/3.5/4.1)
    var s2: fx = 4.1fx;   // block2 speed  (2.0/3.0/3.5/4.1)
    var d2: angle = 12deg; // block2 fan spacing (0.20944/0.261799/0.349066/0.436332 rad)
    if rank == RANK_EASY {
        g = 4; w = 6; s1 = 1.5fx; s2 = 2.0fx; d2 = 25deg;
    } else if rank == RANK_NORMAL {
        g = 8; w = 6; s1 = 2.5fx; s2 = 3.0fx; d2 = 20deg;
    } else if rank == RANK_HARD {
        g = 8; w = 6; s1 = 3.5fx; s2 = 3.5fx; d2 = 15deg;
    }

    // Block 1: source etSprite(0,13,8), etAim(0,1), etAngle(%ANGLE_PLAYER, 2deg) once;
    // counts 1,2,...,g; the aim direction is snapshotted once at this block's start.
    var aim1: angle = aim_player();
    var f: int = 1;
    for i1 in 0..g {
        fire_fan(TH15_BULLET, 8, aim1, f, 2deg, s1);
        f = f + 1;
        wait(w);
    }

    // Block 2: source etSprite(0,18,4), re-reads ANGLE_PLAYER here; counts continue f,f+1,...
    var aim2: angle = aim_player();
    for i2 in 0..g {
        fire_fan(TH15_BIG_BALL, 4, aim2, f, d2, s2);
        f = f + 1;
        wait(w);
    }
}

// ---------------- Boss1_at2 (source 173-229) ----------------
async sub boss1_at2() {
    var rank: int = global(GVAR_RANK);
    var first_wait: int = 150; // source wait 300/300/100/150
    var m: int = 9;            // speed layers (source etCount(1,1,3/3/6/9))
    var s0: fx = 5.0fx;        // first-layer speed (source 1.0/1.0/3.0/5.0)
    var period: int = 80;      // source 160/160/80/80
    if rank == RANK_EASY {
        first_wait = 300; m = 3; s0 = 1.0fx; period = 160;
    } else if rank == RANK_NORMAL {
        first_wait = 300; m = 3; s0 = 1.0fx; period = 160;
    } else if rank == RANK_HARD {
        first_wait = 100; m = 6; s0 = 3.0fx; period = 80;
    }
    wait(first_wait);
    for i in 0..600 {
        // source etAngle(1, %ANGLE_PLAYER + RANDRAD/32, 0): re-aim each wave + random offset
        var base: angle = aim_player() + (((rand(65536) - 32768) / 32) as angle);
        fire_stack(TH15_OVAL, 3, base, m, s0, 0.8fx);
        wait(period);
    }
}

// ---------------- real boss (source Boss entry state + Boss1 body) ----------------
async sub boss_body() {
    set_invuln(65535);
    set_hitbox(24fx);   // source setHitbox(48,48) -> radius 24
    set_hurtbox(20fx);  // source setHurtbox(40,40) -> radius 20
    // spawned at (0,128); moveLimit handled per frame in mv_step.
    mv_wait(60);        // source prelude wait(60)
    spawn boss1_at2();
    loop {
        spawn boss1_at();      // Boss1_388 top
        mv_wait(120);
        mv_rand();             // moveRand(60,4,1.0)
        mv_wait(80);
        spawn boss1_at();      // second call in the cycle
        mv_wait(120);
        mv_rand();
        mv_wait(80);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1700, 0, 0, 0, boss_body);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
